head.script:
// 담당 범위 : dateValidSetCustom true / false / 미설정, dateValidSet 전제, dateValidCheck 연동, invalidMessageFunc 사용자 처리, Empty String 입력
//  - "Body Column 에서만 동작하며 다른 영역의 Column 에 설정 시 무시됩니다." 는 validation 에서 제외
//    (편집 입력이 가능한 Body Column 전용 속성이며 Header / SubTotal / Footer Column 은 입력 수단이 없어 설정 영역 con 옵션 미생성)
//  - 가이드 예제의 팝업(popup.xml) 방식 대신 결과창 기록(사용자 메시지) + setValueCancel(원복)으로 사용자 처리를 구현
//    (가이드 예제의 popup.xml 은 프로젝트에 없고, 팝업이 열리면 편집 유지 / 포커스 / 입력창 값 관찰과 alert 수집이 섞이므로 결과창으로 대체)



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > dateValidSetCustom]<br/>inputType='calendar' 인 Column 에 유효하지 않은 날짜/시간이 입력된 경우 처리를 직접 구현할지 설정합니다.",
    "validation" : [
        "Column 의 dateValidSet=true 인 경우에 동작하며 오류 메시지와 입력값 복원을 직접 처리할때 설정합니다.",
        "true 설정 시, 유효하지 않은 날짜/시간(Empty String 불포함)이 입력된 경우 오류 메시지와 입력값 복원을 처리하지 않습니다.",
        "true 설정 시, 입력값에 대해 별도의 처리나 오류 메시지를 표시하려면 invalidMessageFunc 속성의 사용자 정의 함수에 정의하여야 합니다.",
        "false 설정 시, 유효하지 않은 날짜/시간(Empty String 불포함)이 입력된 경우 Column 의 dateValidSet 속성에 설정된 값에 맞게 동작합니다.",
        "미설정 시, 유효하지 않은 날짜/시간(Empty String 불포함)이 입력된 경우 Column 의 dateValidSet 속성에 설정된 값에 맞게 동작합니다.",
        "Column 의 dateValidCheck=true, dateValidSet=false, dateValidSetCustom=true 일때 유효하지 않은 날짜/시간 입력 시 invalidMessageFunc 사용자 함수가 실행됩니다. 해당 동작은 dateValidSetCustom 속성과 관계없이 dateValidCheck 속성에 의해 발생하는 동작이므로 주의해야 합니다.",
        "dateValidSet=true, dateValidSetCustom=true 인 Column 에 값 입력 시 입력값이 빈 문자열이면 유효성 검증 실패로 처리되지 않으므로 편집이 정상적으로 종료됩니다.",
        "dateValidSet=true, dateValidSetCustom=true 인 Column 에 값 입력 시 입력값이 유효하지 않은 날짜이면 편집을 시작한 시점의 값으로 되돌리지 않고 입력한 값이 화면에 그대로 남습니다.",
        "dateValidSet=true, dateValidSetCustom=true 인 Column 에 값 입력 시 유효성 검증은 실패로 처리되므로 편집이 종료되지 않고 포커스가 해당 셀에 남습니다.",
        "dateValidSet=true, dateValidSetCustom=true 인 Column 에 값 입력 시 시스템 기본 메시지 알림창이 표시되지 않습니다.",
    ]
}

// 사용자 처리 함수가 표시하는 사용자 메시지
scwin.userMessage = "유효하지 않은 날짜입니다. 다시 입력하세요.";

// 편집 종료 결과 출력 지연 타이머
scwin.editEndTimer = null;



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // validation 1, 2, 4, 5, 6, 10 : 엔진이 표시하는 alert 문구를 결과창에 기록 (기록 후 원래 alert 도 그대로 실행, 페이지 종료 시 원복)
    scwin.orgAlert = window.alert;
    window.alert = function (msg) {
        wf_body_bottom.getObj("scwin").setReturnValue("alert : " + msg);
        return scwin.orgAlert.apply(window, arguments);
    };

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    // (dateValidSetCustom=true, dateValidSet=true, dateValidCheck / invalidMessageFunc 미설정)
    con_dateValidSetCustom.setValue("2");
    con_dateValidSet.setValue("2");
    con_dateValidCheck.setValue("1");
    con_invalidMessageFunc.setValue("");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 페이지 종료 시 alert 후킹 원복
scwin.onpageunload = function () {
    if (scwin.orgAlert) {
        window.alert = scwin.orgAlert;
    }
};



// comp 생성
//  - cal : 검증 대상 Body Column (inputType="calendar" + dataType="date", calendarValueType="yearMonthDate")
//          dateValidSetCustom / dateValidSet / dateValidCheck / invalidMessageFunc 는 con (미설정이면 속성 자체를 넣지 않음)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] cal Row 0 은 20261001, Row 1 은 20261015\n[절차] 결과창 clear -> cal 셀 클릭 -> Ctrl+A 후 유효하지 않은 날짜(예: 20261345) 입력 또는 Backspace 로 값 삭제 -> 셀 밖(조건 영역) 클릭\n[확인] invalidMessageFunc 호출 줄과 사용자 처리 결과, alert 문구, 편집 종료 결과 줄의 편집 유지 여부와 포커스 위치(입력창 값), DataList 값\n편집이 유지되면 Esc 로 편집을 취소한 뒤 Target 재생성"', '', 'label1');

    // dataList 생성 (calendar Column 바인딩 컬럼은 dataType="date")
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="cal" name="cal" dataType="date"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "cal" : "20261001" },
        { "cal" : "20261015" }
    ], false);

    // con 값 (gdl_boolean 은 라벨로 읽고, 미설정이면 속성 자체를 넣지 않는다)
    let properties = {
        dateValidSetCustom : con_dateValidSetCustom.getText(),
        dateValidSet : con_dateValidSet.getText(),
        dateValidCheck : con_dateValidCheck.getText(),
        invalidMessageFunc : con_invalidMessageFunc.getValue()
    };
    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["oneditend"]);

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:300px;height:120px;" ' + eList + '>';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="260" style="" inputType="text" id="column1" value="cal"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="260" style="" id="cal" inputType="calendar" dataType="date" viewType="icon" calendarValueType="yearMonthDate" ' + cList + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// validation 1, 6 : 유효성 검증 실패 시 실행되는 사용자 함수 (호출 기록만, 반환값 없음)
scwin.target1_cal_invalidMessageFunc = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("invalidMessageFunc 호출 (callerId " + this.callerId + ") : 입력값 " + this.getCaller().getValue());
}



// validation 3 : 사용자 정의 함수에서 직접 구현한 처리 (사용자 메시지 표시 + setValueCancel 로 편집 시작 시점 값 원복)
scwin.target1_cal_customProcess = function () {
    let inputCalendar = this.getCaller();
    let inputValue = inputCalendar.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("사용자 메시지 : " + scwin.userMessage);
    inputCalendar.setValueCancel();
    wf_body_bottom.getObj("scwin").setReturnValue("invalidMessageFunc 호출 (callerId " + this.callerId + ") : 입력값 " + inputValue + " -> 원복 후 입력창 값 " + inputCalendar.getValue());
}



// validation 1 ~ 10 : 셀 밖 클릭으로 편집 종료를 시도한 뒤의 결과 (편집 유지 여부, 포커스 위치와 입력창 값, DataList 값)
//  - 같은 클릭에서 여러 번 발생해도 마지막 상태 1줄만 출력
scwin.target1_oneditend = function (rowIndex, columnIndex, value) {
    clearTimeout(scwin.editEndTimer);
    scwin.editEndTimer = setTimeout(function () {
        scwin.printEditResult(rowIndex, value);
    }, 300);
}



scwin.printEditResult = function (rowIndex, value) {
    let activeEl = document.activeElement;
    let strFocus = "";
    if (activeEl && target1.render.contains(activeEl) && activeEl.tagName === "INPUT") {
        strFocus = "Row " + target1.getFocusedRowIndex() + " cal 입력창 (입력창 값 '" + activeEl.value + "')";
    } else {
        strFocus = "그리드 밖";
    }
    let arrData = [];
    let rowCnt = dlt_bind.getRowCount();
    for (let i = 0; i < rowCnt; i++) {
        arrData.push("Row " + i + " '" + dlt_bind.getCellData(i, "cal") + "'");
    }
    wf_body_bottom.getObj("scwin").setReturnValue("입력값 '" + value + "' -> 편집 유지 : " + target1.isEditing()
        + " / 포커스 : " + strFocus + " / DataList : " + arrData.join(", "));
}
